// Consumer's expectation of the pricing provider's response.
const contract = { total_cents: 'number', currency: 'string' };

// Verify a provider response satisfies every consumer expectation.
function verify(response, contract) {
  for (const key of Object.keys(contract)) {
    if (!(key in response)) return false;        // missing field (the rename)
    if (typeof response[key] !== contract[key]) return false; // wrong type
  }
  return true;
}

const oldResponse = { total_cents: 4200, currency: 'USD' };
const newResponse = { amount_cents: 4200, currency: 'USD' }; // field renamed

console.log('OLD: ' + (verify(oldResponse, contract) ? 'PASS' : 'FAIL'));
console.log('NEW: ' + (verify(newResponse, contract) ? 'PASS' : 'FAIL'));
